protected void saveSalesOrder()
{
    next saveSalesOrder();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        CLRObject clrSalesLines, enumeratorSalesLine;
        CLRObject clrDiscountLines, enumeratorDiscountLine;
        CLRObject clrPriceLines, enumeratorPriceLine;
        SalesLine salesLine;

        ttsBegin;

        clrSalesLines = crtSalesTransaction.get_SalesLines();
        enumeratorSalesLine = clrSalesLines.GetEnumerator();
        while (enumeratorSalesLine.MoveNext())
        {
            Microsoft.Dynamics.Commerce.Runtime.DataModel.SalesLine crtSalesLine = enumeratorSalesLine.get_Current();
            salesLine = SalesLine::findInventTransId(crtSalesLine.get_LineId());

            // First delete all margin adjustment history
            GUPMarginComponentAdjustmentHistory::deleteHistory(salesLine.RecId);

            clrPriceLines = crtSalesLine.get_PriceLines();
            enumeratorPriceLine = clrPriceLines.GetEnumerator();
            while (enumeratorPriceLine.MoveNext())
            {
                Microsoft.Dynamics.Commerce.Runtime.DataModel.PriceLine crtPriceLine = enumeratorPriceLine.get_Current();

                if (crtPriceLine is Microsoft.Dynamics.Commerce.Runtime.DataModel.PriceAdjustmentPriceLine)
                //if (crtPriceLine is Microsoft.Dynamics.Commerce.Runtime.DataModel.GlobalUnifiedPricingAdjustmentPriceLine)
                {
                    //Microsoft.Dynamics.Commerce.Runtime.DataModel.GlobalUnifiedPricingAdjustmentPriceLine adjustmentPriceLine = crtPriceLine as Microsoft.Dynamics.Commerce.Runtime.DataModel.GlobalUnifiedPricingAdjustmentPriceLine;

                    RetailPeriodicDiscount  periodicDiscount;
                    RetailPeriodicDiscountLine periodicDiscountLine;
                    GUPPriceComponentCodeSetup marginComponentSetup;

                    select firstonly marginComponentSetup
                    order by marginComponentSetup.CalculationSequence
                    join periodicDiscount
                        where marginComponentSetup.PriceComponentCodeName == periodicDiscount.PriceComponentCodeName
                    join periodicDiscountLine
                    where periodicDiscount.OfferId == periodicDiscountLine.OfferId &&
                        periodicDiscountLine.recId ==  crtPriceLine.get_RecordId() &&
                        periodicDiscount.Status == RetailDisabledEnabled::Enabled &&
                        periodicDiscount.IsGupDiscount == NoYes::Yes &&
                        periodicDiscount.PeriodicDiscountType == RetailDiscountOfferTypeBase::Promotion;

                    if (periodicDiscount)
                    {
                        GUPMarginComponentAdjustmentHistory   marginComponentAdjustmentHistory;
                        marginComponentAdjustmentHistory.clear();
                        marginComponentAdjustmentHistory.SalesLine = salesLine.RecId;
                        marginComponentAdjustmentHistory.MarginComponentCode = periodicDiscount.PriceComponentCodeName;
                        marginComponentAdjustmentHistory.marginComponentAdjustment = periodicDiscount.OfferId;
                        marginComponentAdjustmentHistory.CalculationSequence = marginComponentSetup.CalculationSequence;
                        //marginComponentAdjustmentHistory.Amount = adjustmentPriceLine.get_AdjustedAmount();
                        marginComponentAdjustmentHistory.insert();
                    }
                }
            }
        }

        ttscommit;
    }
}
